// Generated by daily/build-engine.mjs from the production game's physics.
const width = 440;
const floor = 471;
const line = 86;
const left = 7;
const right = width - left;
const spawnY = 39;
const step = 1 / 120;
const clamp = (value, min, max) => Math.max(min, Math.min(value, max));
const reviveInterval = 2000;
const ticketInterval = 2000;
const finalPairPoints = 500;
const dangerSeconds = 1.5;
const rulesVersion = 4;
const tickRate = 120;
const maxTicks = 120 * 60 * 12;
const maxActions = 850;
const levels = [{"radius":12,"points":0},{"radius":15,"points":1},{"radius":18,"points":3},{"radius":21,"points":6},{"radius":24,"points":10},{"radius":27,"points":11},{"radius":30,"points":12},{"radius":33,"points":13},{"radius":34.5,"points":14},{"radius":36,"points":15},{"radius":39,"points":17},{"radius":42,"points":19},{"radius":45,"points":21},{"radius":49,"points":28},{"radius":53,"points":36},{"radius":57,"points":40},{"radius":62,"points":45},{"radius":70,"points":100}];

function replay(seed, actions, finalTick, version = rulesVersion) {
  if (!Array.isArray(actions) || actions.length > maxActions || !Number.isInteger(finalTick) || finalTick < 1 || finalTick > maxTicks) return null;
  let dailyDraw = 0;
  const dailySession = { seed };
  let balls = [], particles = [];
  let score = 0, coins = 0, tickets = 0, cooldown = 0, drops = 0, highestLevel = 0, roundTick = 0;
  let state = "playing", aim = width / 2, removalMode = false;
  let shownLevel = randomLevel(), nextLevel = randomLevel();
  const divineLevel = levels.length - 1;
  const cilantroLevel = divineLevel - 1;
  const rank = { open: false }, result = { close() {} }, profile = { best: 0 };
  const noOp = () => {};
  const wakeSound = noOp, updateDropPreview = noOp, updateRemovalControl = noOp, playSound = noOp;
  const burst = noOp, saveProfile = noOp, updateHud = noOp, showCombo = noOp, celebrate = noOp, recordDailyAction = noOp;
  function isDailyMode() { return true; }
  function activeRulesVersion() { return version; }
  function finishDailyAtLimit() { state = "ended"; }
  function setRemovalMode(active) { removalMode = active; }
  function showResult() { state = coins > 0 ? "revive" : "ended"; }

function dailyRoll(seed, index) {
  let number = (seed + Math.imul(index + 1, 0x9e3779b9)) >>> 0;
  number = Math.imul(number ^ (number >>> 16), 0x21f0aaad);
  number = Math.imul(number ^ (number >>> 15), 0x735a2d97);
  return ((number ^ (number >>> 15)) >>> 0) / 0x100000000;
}

function wideDrop(value, top) {
  if (value < .18) return top - 3;
  if (value < .40) return top - 2;
  return value < .70 ? top - 1 : top;
}

function dailyPiece(seed, index, levelCount) {
  const value = dailyRoll(seed, index);
  const top = Math.min(3 + Math.floor(index / 36), levelCount - 4);
  if (top === 3) {
    if (value < .36) return 0;
    if (value < .65) return 1;
    return value < .86 ? 2 : 3;
  }
  return wideDrop(value, top);
}

function earlyDropCap() {
  return balls.reduce((maximum, ball) => ball.dead ? maximum : Math.max(maximum, ball.level), 0);
}

function mixedDrop(value) {
  if (highestLevel < 4) {
    const cap = earlyDropCap();
    let weight = value * ((cap + 1) * (cap + 2) / 2);
    for (let level = 0; level < cap; level++) {
      weight -= level + 1;
      if (weight < 0) return level;
    }
    return cap;
  }
  if (value < .30) return Math.floor(value / .30 * 4);
  const top = clamp(highestLevel - 1, 3, levels.length - 4);
  return wideDrop((value - .30) / .70, top);
}

function lowerEarlyQueue() {
  if (activeRulesVersion() < 4 || highestLevel >= 4) return;
  const cap = earlyDropCap();
  if (shownLevel <= cap && nextLevel <= cap) return;
  shownLevel = Math.min(shownLevel, cap);
  nextLevel = Math.min(nextLevel, cap);
  updateDropPreview();
}

function randomLevel() {
  if (activeRulesVersion() >= 4) {
    const value = dailySession ? dailyRoll(dailySession.seed, dailyDraw++) : Math.random();
    return mixedDrop(value);
  }
  if (dailySession) return dailyPiece(dailySession.seed, dailyDraw++, levels.length);
  const value = Math.random();
  const highestDrop = clamp(highestLevel - 2, 3, levels.length - 4);
  if (highestDrop === 3) {
    if (value < .36) return 0;
    if (value < .65) return 1;
    if (value < .86) return 2;
    return 3;
  }
  return wideDrop(value, highestDrop);
}

function inspectionRemaining(count) {
  return count >= 25 ? Math.max(0, 3 - (count % 25)) : 0;
}

function dangerLine(count) {
  return line + (inspectionRemaining(count) > 0 ? 16 : 0);
}

function windAt(throwNumber) {
  if (throwNumber % 11 !== 0) return 0;
  const distance = activeRulesVersion() === 2 ? 12 : width / 4;
  return throwNumber % 22 === 0 ? distance : -distance;
}

function windAim(x, radius, wind) {
  if (activeRulesVersion() === 2 || !wind) return x;
  return clamp(x, left + radius + Math.max(0, -wind), right - radius - Math.max(0, wind));
}

function removePiece(ball) {
  if (!removalMode || !ball || tickets === 0) return;
  const index = balls.indexOf(ball);
  if (index < 0) return;
  recordDailyAction("t", index);
  balls.splice(index, 1);
  lowerEarlyQueue();
  tickets--;
  burst(ball.x, ball.y, levels[ball.level].accent, 16);
  setRemovalMode(false);
  playSound("remove");
}

function addScore(points) {
  coins += Math.floor((score + points) / reviveInterval) - Math.floor(score / reviveInterval);
  const interval = activeRulesVersion() === 2 ? 300 : ticketInterval;
  tickets += Math.floor((score + points) / interval) - Math.floor(score / interval);
  score += points;
  if (!isDailyMode() && score > profile.best) {
    profile.best = score;
    saveProfile();
  }
  updateHud();
}

function makeBall(level, x, y, vx = 0, vy = 0) {
  const radius = levels[level].radius;
  return {
    level, x, y, vx, vy, radius, invMass: 1 / (radius * radius),
    rotation: (Math.random() - .5) * .22, spin: 0, age: 0, danger: 0,
    contacted: false, dead: false, chain: null
  };
}

function drop() {
  if (state !== "playing" || rank.open || removalMode || cooldown > 0) return;
  wakeSound();
  lowerEarlyQueue();
  if (isDailyMode()) aim = Math.round(clamp(aim, 0, width) * 100) / 100;
  recordDailyAction("d", Math.round(aim * 100));
  const radius = levels[shownLevel].radius;
  const wind = windAt(drops + 1);
  const x = windAim(aim, radius, wind);
  const ball = makeBall(shownLevel, clamp(x + wind, left + radius, right - radius), Math.max(spawnY, radius + 3), 0, 42);
  ball.chain = { drop: ++drops, count: 0 };
  balls.push(ball);
  shownLevel = nextLevel;
  nextLevel = randomLevel();
  updateDropPreview();
  cooldown = .32;
  updateRemovalControl();
  playSound(wind ? "wind" : "drop");
  if (drops % 25 === 0) playSound("inspection");
}

function mergeChain(a, b) {
  // Expired pieces can still merge, but they no longer belong to a recent drop.
  const first = a.age <= 1.65 ? a.chain : null;
  const second = b.age <= 1.65 ? b.chain : null;
  if (!first && !second) return null;
  const source = !second || (first && first.drop > second.drop) ? first : second;
  return { drop: source.drop, count: source.count + 1 };
}

function clearBoard(x, y, comboBonus) {
  const stride = Math.max(1, Math.ceil(balls.length / 18));
  balls.forEach((ball, index) => {
    if (index % stride === 0) burst(ball.x, ball.y, levels[ball.level].accent, 7);
  });
  balls.length = 0;
  cooldown = Math.max(cooldown, .55);
  coins++;
  addScore(finalPairPoints + comboBonus);
  burst(x, y, "#6b9b42", 38);
  celebrate("双神·香菜 · 全场清空", "+500 分 · +1 复活币 · 本局继续", "gold");
  playSound("clear");
}

function merge(a, b) {
  a.dead = b.dead = true;
  const x = (a.x + b.x) / 2;
  const y = (a.y + b.y) / 2;
  const level = a.level + 1;
  const chain = mergeChain(a, b);
  const comboBonus = chain ? Math.min(24, (chain.count - 1) * 3) : 0;
  if (comboBonus > 0) showCombo(chain.count, comboBonus);
  if (level === levels.length) {
    clearBoard(x, y, comboBonus);
    return true;
  }
  const merged = makeBall(level, x, y, (a.vx + b.vx) * .28, Math.min(10, (a.vy + b.vy) * .28));
  merged.contacted = true;
  merged.age = .34;
  merged.chain = chain;
  balls.push(merged);
  highestLevel = Math.max(highestLevel, level);
  addScore(levels[level].points + comboBonus);
  if (level === cilantroLevel) {
    celebrate("香菜觉得你很不错哦", "两株香菜可合成神·香菜");
    playSound("cilantro");
  } else if (level === divineLevel) {
    celebrate("你得到了香菜的青睐", "神·香菜降临", "gold");
    burst(x, y, "#ffd768", 40);
    playSound("divine");
  } else {
    playSound(comboBonus > 0 ? "combo" : "merge", level + (chain?.count ?? 0));
  }
  burst(x, y, levels[level].accent, level >= cilantroLevel ? 48 : 14);
  return false;
}

function bound(ball) {
  const { radius } = ball;
  if (ball.x < left + radius) {
    ball.x = left + radius;
    ball.vx = Math.max(0, -ball.vx * .21);
  } else if (ball.x > right - radius) {
    ball.x = right - radius;
    ball.vx = Math.min(0, -ball.vx * .21);
  }
  if (ball.y > floor - radius) {
    ball.y = floor - radius;
    ball.vy = ball.vy > 50 ? -ball.vy * .17 : Math.min(0, ball.vy);
    ball.vx *= .971;
    ball.contacted = true;
  }
  if (ball.y < radius) {
    ball.y = radius;
    ball.vy = Math.max(0, ball.vy);
  }
}

function collide(a, b, distance, dx, dy, overlap) {
  const nx = distance > .001 ? dx / distance : 1;
  const ny = distance > .001 ? dy / distance : 0;
  const mass = a.invMass + b.invMass;
  const correction = Math.max(0, overlap - .025) * .87 / mass;
  a.x -= nx * correction * a.invMass;
  a.y -= ny * correction * a.invMass;
  b.x += nx * correction * b.invMass;
  b.y += ny * correction * b.invMass;
  a.contacted = b.contacted = true;

  const vx = b.vx - a.vx;
  const vy = b.vy - a.vy;
  const normal = vx * nx + vy * ny;
  if (normal >= 0) return;
  const bounce = normal < -105 ? .17 : 0;
  const force = -normal * (1 + bounce) / mass;
  const tangent = vx * -ny + vy * nx;
  const friction = clamp(-tangent / mass, -force * .15, force * .15);
  const ix = force * nx - friction * ny;
  const iy = force * ny + friction * nx;
  a.vx -= ix * a.invMass;
  a.vy -= iy * a.invMass;
  b.vx += ix * b.invMass;
  b.vy += iy * b.invMass;
}

function advance() {
  roundTick++;
  if (isDailyMode() && roundTick >= maxTicks) {
    finishDailyAtLimit();
    return;
  }
  cooldown = Math.max(0, cooldown - step);
  for (const ball of balls) {
    ball.age += step;
    ball.vy = Math.min(ball.vy + 1010 * step, 690);
    ball.vx *= .999;
    ball.x += ball.vx * step;
    ball.y += ball.vy * step;
    ball.spin += (ball.vx / ball.radius - ball.spin) * .072;
    ball.rotation = clamp((ball.rotation + ball.spin * step) * .997, -.95, .95);
    bound(ball);
  }
  contacts: for (let iteration = 0; iteration < 6; iteration++) {
    const count = balls.length;
    for (let i = 0; i < count; i++) {
      const a = balls[i];
      if (a.dead) continue;
      for (let j = i + 1; j < count; j++) {
        const b = balls[j];
        if (b.dead) continue;
        const dx = b.x - a.x;
        const dy = b.y - a.y;
        const size = a.radius + b.radius;
        const distance2 = dx * dx + dy * dy;
        if (distance2 >= size * size) continue;
        if (a.level === b.level) {
          if (merge(a, b)) break contacts;
          break;
        }
        const distance = Math.sqrt(distance2);
        collide(a, b, distance, dx, dy, size - distance);
      }
      if (!a.dead) bound(a);
    }
  }
  if (balls.some(ball => ball.dead)) balls = balls.filter(ball => !ball.dead);
  const limit = dangerLine(drops);
  for (const ball of balls) {
    const parked = ball.contacted && ball.age > .65 && Math.hypot(ball.vx, ball.vy) < 85;
    ball.danger = ball.y - ball.radius < limit && parked
      ? ball.danger + step : Math.max(0, ball.danger - 2 * step);
    if (ball.danger > dangerSeconds) {
      showResult();
      break;
    }
  }
  for (const particle of particles) {
    particle.life -= step;
    particle.x += particle.vx * step;
    particle.y += particle.vy * step;
    particle.vy += 85 * step;
  }
  if (particles.some(particle => particle.life <= 0)) particles = particles.filter(particle => particle.life > 0);
}

function revive() {
  if (state !== "revive" || coins <= 0) return;
  wakeSound();
  recordDailyAction("r");
  coins--;
  const limit = dangerLine(drops);
  balls = balls.filter(ball => {
    if (ball.y - ball.radius >= limit) {
      ball.danger = 0;
      return true;
    }
    burst(ball.x, ball.y, levels[ball.level].accent, 14);
    return false;
  });
  lowerEarlyQueue();
  state = "playing";
  cooldown = .22;
  result.close();
  updateHud();
  playSound("revive");
}

  function advanceTo(tick) {
    while (roundTick < tick && state === "playing") advance();
    return roundTick === tick;
  }
  for (const action of actions) {
    if (!Array.isArray(action) || action.length < 2 || action.length > 3 ||
        !Number.isInteger(action[0]) || action[0] < roundTick || action[0] > finalTick ||
        !advanceTo(action[0])) return null;
    const [, kind, arg] = action;
    if (kind === "d" && action.length === 3 && state === "playing" && cooldown === 0 &&
        Number.isInteger(arg) && arg >= 0 && arg <= width * 100) {
      aim = arg / 100; drop();
    } else if (kind === "t" && action.length === 3 && state === "playing" && tickets > 0 &&
               Number.isInteger(arg) && arg >= 0 && arg < balls.length) {
      setRemovalMode(true); removePiece(balls[arg]);
    } else if (kind === "r" && action.length === 2 && state === "revive") {
      revive();
    } else if (kind === "f" && action.length === 2 && state === "revive") {
      state = "ended";
    } else {
      return null;
    }
  }
  if (!advanceTo(finalTick) || state !== "ended") return null;
  return { score, drops };
}


const utf8 = new TextEncoder();
const decoder = new TextDecoder();
const maxBody = 24 * 1024;
const hour = 3600000;

function dayAt(now) {
  return new Date(now + 8 * hour).toISOString().slice(0, 10);
}

function seedFor(day) {
  let hash = 2166136261;
  for (const char of day) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619);
  return hash >>> 0;
}

const to64 = bytes => btoa(String.fromCharCode(...bytes)).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/, "");
const from64 = s => Uint8Array.from(atob(s.replaceAll("-", "+").replaceAll("_", "/")), c => c.charCodeAt(0));

async function signingKey(secret) {
  return crypto.subtle.importKey("raw", utf8.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]);
}

async function sign(value, key) {
  const payload = to64(utf8.encode(JSON.stringify(value)));
  const sig = await crypto.subtle.sign("HMAC", key, utf8.encode(payload));
  return payload + "." + to64(new Uint8Array(sig));
}

async function verify(token, key) {
  if (typeof token !== "string" || token.length > 768 || !/^[\w-]+\.[\w-]+$/.test(token)) return null;
  try {
    const [payload, sig] = token.split(".");
    if (!await crypto.subtle.verify("HMAC", key, from64(sig), utf8.encode(payload))) return null;
    return JSON.parse(decoder.decode(from64(payload)));
  } catch {
    return null;
  }
}

class BadRequest extends Error {}
async function readJson(request) {
  if (!request.body || Number(request.headers.get("Content-Length")) > maxBody) throw new BadRequest("请求过大");
  const reader = request.body.getReader();
  let length = 0, buffer = "";
  const decode = new TextDecoder();
  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    length += value.byteLength;
    if (length > maxBody) {
      await reader.cancel();
      throw new BadRequest("请求过大");
    }
    buffer += decode.decode(value, { stream: true });
  }
  try {
    const value = JSON.parse(buffer + decode.decode());
    if (!value || Array.isArray(value) || typeof value !== "object") throw Error();
    return value;
  } catch {
    throw new BadRequest("请求格式不正确");
  }
}

function supportsRules(version) {
  return version === 2 || version === 3 || version === rulesVersion;
}

async function board(db, day, version) {
  const query = `SELECT name, score FROM (
    SELECT name, score, submitted,
      ROW_NUMBER() OVER (PARTITION BY player ORDER BY score DESC, submitted ASC, id ASC) AS best
    FROM entries WHERE day = ? AND rules_version = ?
  ) WHERE best = 1 ORDER BY score DESC, submitted ASC, name ASC LIMIT 25`;
  const { results } = await db.prepare(query).bind(day, version).all();
  return results;
}

function d1Store(db) {
  return {
    board: (day, version) => board(db, day, version),
    score: id => db.prepare("SELECT score FROM entries WHERE id = ?").bind(id).first(),
    submit: ({ id, player, day, name, score, submitted, rules_version }) =>
      db.prepare("INSERT INTO entries (id, player, day, name, score, submitted, rules_version) VALUES (?, ?, ?, ?, ?, ?, ?) ON CONFLICT(id) DO NOTHING")
        .bind(id, player, day, name, score, submitted, rules_version).run(),
  };
}

async function handleRequest(request, env, now = Date.now()) {
  const origin = request.headers.get("Origin");
  const allowed = (env.ALLOW_ORIGINS || "").split(/\s+/);
  const headers = new Headers({ "Cache-Control": "no-store", "Content-Type": "application/json; charset=utf-8", "Vary": "Origin" });
  const reply = (data, status = 200) => new Response(JSON.stringify(data), { status, headers });
  if (origin && !allowed.includes(origin)) return reply({ error: "这个网页地址未配置今日榜" }, 403);
  if (origin) headers.set("Access-Control-Allow-Origin", origin);
  if (request.method === "OPTIONS") {
    headers.set("Access-Control-Allow-Headers", "Content-Type");
    headers.set("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
    return new Response(null, { status: 204, headers });
  }
  const url = new URL(request.url);
  const path = url.pathname;
  const day = dayAt(now);
  const store = env.STORE ?? d1Store(env.DB);
  try {
    if (request.method === "GET" && path === "/board") {
      const version = Number(url.searchParams.get("rulesVersion") ?? 2);
      if (!supportsRules(version)) return reply({ error: "请刷新游戏后再开始" }, 409);
      return reply({ day, rulesVersion: version, entries: await store.board(day, version) });
    }
    if (request.method !== "POST" || !["/start", "/submit"].includes(path)) return reply({ error: "接口不存在" }, 404);
    if (typeof env.HMAC_SECRET !== "string" || env.HMAC_SECRET.length < 32) return reply({ error: "今日榜暂未配置" }, 503);
    const key = await signingKey(env.HMAC_SECRET);
    const body = await readJson(request);
    if (path === "/start") {
      const version = body.rulesVersion;
      if (!supportsRules(version)) return reply({ error: "请刷新游戏后再开始" }, 409);
      const identity = await verify(body.player, key);
      const playerId = identity?.type === "player" ? identity.id : crypto.randomUUID();
      const player = await sign({ type: "player", id: playerId }, key);
      const seed = seedFor(day);
      const run = await sign({ type: "run", id: crypto.randomUUID(), player: playerId, day, seed, started: now, rulesVersion: version }, key);
      return reply({ day, seed, run, player, rulesVersion: version });
    }
    const run = await verify(body.run, key);
    if (run?.type !== "run" || !supportsRules(run.rulesVersion) || run.day !== day ||
        now < run.started || now - run.started > 2 * hour) {
      return reply({ error: "对局已过期，请重新开始" }, 409);
    }
    if (!Number.isSafeInteger(body.tick) || body.tick / tickRate * 1000 > now - run.started + 8000 ||
        !Number.isSafeInteger(body.score) || typeof body.name !== "string") {
      return reply({ error: "对局记录格式不正确" }, 422);
    }
    const name = body.name.trim().normalize("NFC");
    if (!name || name.length > 18 || /[\p{Cc}\p{Cf}]/u.test(name)) return reply({ error: "昵称须为 1–18 个可见字符" }, 422);

    const existing = await store.score(run.id);
    if (existing) return reply({ day, score: existing.score });
    const verified = replay(run.seed, body.actions, body.tick, run.rulesVersion);
    if (!verified || !verified.drops || verified.score !== body.score) {
      return reply({ error: "回放无法重现本局成绩" }, 422);
    }
    await store.submit({ id: run.id, player: run.player, day, name, score: verified.score, submitted: now, rules_version: run.rulesVersion });
    const submitted = await store.score(run.id);
    return reply({ day, score: submitted.score });
  } catch (error) {
    if (error instanceof BadRequest) return reply({ error: error.message }, 400);
    console.error(error);
    return reply({ error: "今日榜暂时不可用" }, 503);
  }
}



function supabaseStore(url, key, request = fetch) {
  const headers = { apikey: key, "Content-Type": "application/json" };
  if (!key.startsWith("sb_secret_")) headers.Authorization = "Bearer " + key;
  async function call(path, options = {}) {
    const response = await request(url + "/rest/v1/" + path, { ...options, headers: { ...headers, ...options.headers } });
    if (!response.ok) throw new Error("Leaderboard database error " + response.status);
    return response.status === 204 || options.method === "POST" && path.startsWith("cilantro_daily_entries")
      ? null : response.json();
  }
  return {
    signingSecret: () => call("rpc/cilantro_daily_signing_key", { method: "POST", body: "{}" }),
    board: (day, version) => call("rpc/cilantro_daily_board_for_rules", {
      method: "POST", body: JSON.stringify({ p_day: day, p_version: version }),
    }),
    async score(id) {
      const rows = await call("cilantro_daily_entries?id=eq." + encodeURIComponent(id) + "&select=score&limit=1");
      return rows[0] ?? null;
    },
    submit: entry => call("cilantro_daily_entries", {
      method: "POST",
      headers: { Prefer: "resolution=ignore-duplicates,return=minimal" },
      body: JSON.stringify(entry),
    }),
  };
}

function supabaseHandler(env) {
  const prefix = "/cilantro-board";
  let signingSecret;
  return async request => {
    const url = new URL(request.url);
    const offset = url.pathname.indexOf(prefix + "/");
    if (offset >= 0) url.pathname = url.pathname.slice(offset + prefix.length);
    let config = env;
    const allowed = env.ALLOW_ORIGINS.split(/\s+/);
    const origin = request.headers.get("Origin");
    if (request.method === "POST" && ["/start", "/submit"].includes(url.pathname) &&
        (!origin || allowed.includes(origin))) {
      try {
        signingSecret ??= env.STORE.signingSecret();
        config = { ...env, HMAC_SECRET: await signingSecret };
      } catch {
        signingSecret = undefined;
      }
    }
    return handleRequest(new Request(url, request), config);
  };
}

const projectUrl = Deno.env.get("SUPABASE_URL");
const serviceKey = JSON.parse(Deno.env.get("SUPABASE_SECRET_KEYS") || "{}").default ||
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
if (!projectUrl || !serviceKey) throw new Error("Missing leaderboard configuration");
Deno.serve(supabaseHandler({
  ALLOW_ORIGINS: Deno.env.get("CILANTRO_ALLOWED_ORIGINS") ||
    "https://xiangcai.yinjinghang.com http://xiangcai.yinjinghang.com",
  STORE: supabaseStore(projectUrl, serviceKey)
}));
